namespace m1_gemv {
constexpr int N_LANES = 16;
constexpr int K_LANES = 4;
constexpr int K_GROUP = 128;
constexpr int WAVES_K = 8;
constexpr int BLOCK_SIZE = 64 * WAVES_K;
struct Args {
const unsigned char* a;
const unsigned char* b;
unsigned short* out;
const unsigned char* sfa;
const unsigned char* sfb;
int n, k;
int stride_a, stride_b, stride_c, stride_sfa, stride_sfb;
};
__global__ void m1_gemv_dot2_kernel(Args) ;
struct Shape { int n, k; };
constexpr Shape SHAPES[] = {
{768,7168}, {2048,7168}, {6144,7168}, {7168,384}, {7168,768},
{7168,1024}, {7168,3072}, {7168,7168}, {7168,16384},
{16384,1536}, {65536,1536}
};
constexpr int SHAPE_COUNT = sizeof(SHAPES) / sizeof(SHAPES[0]);
static bool overlap(const void* a, uint64_t as, const void* b, uint64_t bs) {
const uintptr_t aa = reinterpret_cast<uintptr_t>(a), bb = reinterpret_cast<uintptr_t>(b);
return aa >= bb ? aa - bb < bs : bb - aa < as;
}
static int validate(int group, int variant, const void* a, const void* b, void* out,
const void* sfa, const void* sfb, int m, int n, int k) {
if (group < 0 || group >= SHAPE_COUNT || variant != 0) return -1;
if (m != 1 || n != SHAPES[group].n || k != SHAPES[group].k || n % 128 || k % 128) return -2;
if (!a || !b || !out || !sfa || !sfb) return -3;
const uint64_t ab = k, bb = static_cast<uint64_t>(n) * k, cb = static_cast<uint64_t>(n) * 2;
const uint64_t sab = k / 128, sbb = static_cast<uint64_t>(n / 128) * (k / 128);
if (bb > INT_MAX || cb > INT_MAX || sab > INT_MAX || sbb > INT_MAX) return -4;
if (reinterpret_cast<uintptr_t>(a) % 16 || reinterpret_cast<uintptr_t>(b) % 16 ||
reinterpret_cast<uintptr_t>(out) % 2) return -5;
const void* ptrs[] = {a, b, out, sfa, sfb};
const uint64_t sizes[] = {ab, bb, cb, sab, sbb};
for (int i = 0; i < 5; ++i) {
if (sizes[i] > UINTPTR_MAX - reinterpret_cast<uintptr_t>(ptrs[i])) return -6;
for (int j = i + 1; j < 5; ++j) {
if (overlap(ptrs[i], sizes[i], ptrs[j], sizes[j])) return -7;
}
}
return 0;
}
static int launch(int group, int variant, const void* a, const void* b, void* out,
const void* sfa, const void* sfb, int m, int n, int k, void* stream) {
const int checked = validate(group, variant, a, b, out, sfa, sfb, m, n, k);
if (checked) return checked;
const Args args{static_cast<const unsigned char*>(a), static_cast<const unsigned char*>(b),
static_cast<unsigned short*>(out), static_cast<const unsigned char*>(sfa),
static_cast<const unsigned char*>(sfb), n, k, k, k, n, 1, k / 128};
m1_gemv_dot2_kernel<<<dim3(n / N_LANES), dim3(BLOCK_SIZE), 0,
reinterpret_cast<hipStream_t>(stream)>>>(args);
return static_cast<int>(hipGetLastError());
}
}

int run_m1_gemv(int group, int variant, const void* a, const void* b, void* out,
const void* sfa, const void* sfb, void* workspace, uint64_t workspace_bytes,
int m, int n, int k, void* stream) {
if (workspace || workspace_bytes) return -8;
return m1_gemv::launch(group, variant, a, b, out, sfa, sfb, m, n, k, stream);
}

template<int Selector, int Variant, int Split>
inline int launch(const void* a, const void* b, void* out, const void* sfa, const void* sfb, void* ws, uint64_t bytes, int m, int n, int k, void* stream) {
    return run_m1_gemv(Selector, Variant, a, b, out, sfa, sfb, ws, bytes, m, n, k, stream);
}
