// SPDX-License-Identifier: Apache-2.0
// Independent M=1 GEMV prototype. No public kernel or dispatch is changed.

namespace m1_gemv {
constexpr int N_LANES = 16;
constexpr int K_LANES = 4;
constexpr int K_GROUP = 128;
constexpr int WAVES_K = 8;
constexpr int BLOCK_SIZE = 64 * WAVES_K;

// Logical dense strides describe the existing physical bpreshuffle storage.
// B was shuffled from [N/16,16,K/32,2,16] to [N/16,K/32,2,16,16].
struct Args {
    const unsigned char* a;
    const unsigned char* b;
    unsigned short* out;
    const unsigned char* sfa;
    const unsigned char* sfb;
    int n, k;
    int stride_a, stride_b, stride_c, stride_sfa, stride_sfb;
};

#if defined(__HIP_DEVICE_COMPILE__)
#if !defined(__gfx950__)
#error "The M1 GEMV prototype requires gfx950 FP8 conversion and BF16 dot2."
#endif
using U32x4 = unsigned int __attribute__((ext_vector_type(4)));
using I16x2 = short __attribute__((ext_vector_type(2)));

__device__ __forceinline__ unsigned int fp8_pair_to_bf16_bits_low(unsigned int word) {
    // false selects source bytes 0,1. Scale 1 keeps every finite E4M3 value exact.
    return __builtin_bit_cast(unsigned int,
        __builtin_amdgcn_cvt_scalef32_pk_bf16_fp8(word, 1.0f, false));
}
__device__ __forceinline__ unsigned int fp8_pair_to_bf16_bits_high(unsigned int word) {
    // true selects source bytes 2,3 (op_sel:[1,0,0]).
    return __builtin_bit_cast(unsigned int,
        __builtin_amdgcn_cvt_scalef32_pk_bf16_fp8(word, 1.0f, true));
}
__device__ __forceinline__ unsigned int wave_read_bits(unsigned int bits, int source_lane) {
    return static_cast<unsigned int>(__builtin_amdgcn_ds_bpermute(
        source_lane * 4, __builtin_bit_cast(int, bits)));
}
__device__ __forceinline__ float wave_read_float(float value, int source_lane) {
    return __builtin_bit_cast(float, wave_read_bits(__builtin_bit_cast(unsigned int, value), source_lane));
}
__device__ __forceinline__ float dot2_bits(unsigned int a, unsigned int b, float acc) {
    return __builtin_amdgcn_fdot2_f32_bf16(
        __builtin_bit_cast(I16x2, a), __builtin_bit_cast(I16x2, b), acc, false);
}
__device__ __forceinline__ unsigned short fp32_to_bf16_rne(float value) {
    unsigned int bits = __builtin_bit_cast(unsigned int, value);
    if ((bits & 0x7f800000u) == 0x7f800000u) {
        if (bits & 0x007fffffu) bits |= 0x00400000u;
    } else {
        bits += 0x00007fffu + ((bits >> 16) & 1u);
    }
    return static_cast<unsigned short>(bits >> 16);
}

__global__ __launch_bounds__(BLOCK_SIZE)
void m1_gemv_dot2_kernel(Args args) {
    const int tid = __builtin_amdgcn_workitem_id_x();
    const int lane = tid & 63;
    const int wave = __builtin_amdgcn_readfirstlane(tid >> 6);
    const int n_lane = lane & 15;
    const int k_lane = lane >> 4;
    const int n_base = __builtin_amdgcn_workgroup_id_x() * N_LANES;
    const int groups = args.k / K_GROUP;
    float wave_sum = 0.0f;

    // Each wave owns complete K128 groups. Four K lanes cover disjoint 32B
    // portions of that group; the sixteen N lanes own independent outputs.
    for (int group = wave; group < groups; group += WAVES_K) {
        const int k_begin = group * K_GROUP + k_lane * 32;
        unsigned int a_low = 0, a_high = 0;
        if (n_lane < 8) {
            const unsigned int a_word = *reinterpret_cast<const unsigned int*>(args.a + k_begin + n_lane * 4);
            a_low = fp8_pair_to_bf16_bits_low(a_word);
            a_high = fp8_pair_to_bf16_bits_high(a_word);
        }
        // Only 32 producer lanes load/convert the shared A vector. Broadcast
        // converted pairs to all sixteen output channels within each K lane.
        // Four K-lane/N16 chunks are contiguous in the physical shuffled tile.
        const uint64_t b_offset = static_cast<uint64_t>(n_base) * args.stride_b
            + static_cast<uint64_t>(group) * (K_GROUP * N_LANES)
            + k_lane * (32 * N_LANES) + n_lane * 16;
        const U32x4 b_first = *reinterpret_cast<const U32x4*>(args.b + b_offset);
        const U32x4 b_second = *reinterpret_cast<const U32x4*>(args.b + b_offset + N_LANES * 16);
        float group_partial = 0.0f;
#pragma unroll
        for (int word = 0; word < 8; ++word) {
            const int producer = k_lane * N_LANES + word;
            const unsigned int aw_low = wave_read_bits(a_low, producer);
            const unsigned int aw_high = wave_read_bits(a_high, producer);
            const unsigned int bw = word < 4 ? b_first[word & 3] : b_second[word & 3];
            group_partial = dot2_bits(aw_low, fp8_pair_to_bf16_bits_low(bw), group_partial);
            group_partial = dot2_bits(aw_high, fp8_pair_to_bf16_bits_high(bw), group_partial);
        }

        // XOR the K-lane bits only. N-channel identities never mix.
        group_partial += wave_read_float(group_partial, lane ^ 16);
        group_partial += wave_read_float(group_partial, lane ^ 32);
        if (k_lane == 0) {
            const unsigned int sa = args.sfa[group * args.stride_sfa];
            const unsigned int sb = args.sfb[(n_base / 128) * args.stride_sfb + group];
            // E8M0 finite byte e represents 2^(e-127), including e=0.
            // Apply the combined exponent after FP32 K128 reduction, avoiding any
            // scaled BF16 overflow and intermediate FP32 scale-product overflow.
            const float scaled = sa == 255u || sb == 255u
                ? __builtin_bit_cast(float, 0x7fc00000u)
                : __builtin_amdgcn_ldexpf(group_partial, static_cast<int>(sa + sb) - 254);
            wave_sum += scaled;
        }
    }

    // 8*16 floats only: combine K-wave partials before the sole BF16 rounding.
    // No padded M tile, global workspace, atomics, or second kernel launch.
    __shared__ float partials[WAVES_K][N_LANES];
    if (k_lane == 0) partials[wave][n_lane] = wave_sum;
    __builtin_amdgcn_s_waitcnt(0);
    __builtin_amdgcn_s_barrier();
    if (wave == 0 && k_lane == 0) {
        float sum = 0.0f;
#pragma unroll
        for (int source_wave = 0; source_wave < WAVES_K; ++source_wave) {
            sum += partials[source_wave][n_lane];
        }
        args.out[n_base + n_lane] = fp32_to_bf16_rne(sum);
    }
}
#else
__global__ void m1_gemv_dot2_kernel(Args) {}
#endif

#if !defined(__HIP_DEVICE_COMPILE__)
struct Shape { int n, k; };
constexpr Shape SHAPES[] = {
    {768,7168}, {2048,7168}, {6144,7168}, {7168,384}, {7168,768},
    {7168,1024}, {7168,3072}, {7168,7168}, {7168,16384},
    {16384,1536}, {65536,1536}
};
constexpr int SHAPE_COUNT = sizeof(SHAPES) / sizeof(SHAPES[0]);

static bool overlap(const void* a, uint64_t as, const void* b, uint64_t bs) {
    const uintptr_t aa = reinterpret_cast<uintptr_t>(a), bb = reinterpret_cast<uintptr_t>(b);
    return aa >= bb ? aa - bb < bs : bb - aa < as;
}
static int validate(int group, int variant, const void* a, const void* b, void* out,
                    const void* sfa, const void* sfb, int m, int n, int k) {
    if (group < 0 || group >= SHAPE_COUNT || variant != 0) return -1;
    if (m != 1 || n != SHAPES[group].n || k != SHAPES[group].k || n % 128 || k % 128) return -2;
    if (!a || !b || !out || !sfa || !sfb) return -3;
    const uint64_t ab = k, bb = static_cast<uint64_t>(n) * k, cb = static_cast<uint64_t>(n) * 2;
    const uint64_t sab = k / 128, sbb = static_cast<uint64_t>(n / 128) * (k / 128);
    if (bb > INT_MAX || cb > INT_MAX || sab > INT_MAX || sbb > INT_MAX) return -4;
    if (reinterpret_cast<uintptr_t>(a) % 16 || reinterpret_cast<uintptr_t>(b) % 16 ||
        reinterpret_cast<uintptr_t>(out) % 2) return -5;
    const void* ptrs[] = {a, b, out, sfa, sfb};
    const uint64_t sizes[] = {ab, bb, cb, sab, sbb};
    for (int i = 0; i < 5; ++i) {
        if (sizes[i] > UINTPTR_MAX - reinterpret_cast<uintptr_t>(ptrs[i])) return -6;
        for (int j = i + 1; j < 5; ++j) {
            if (overlap(ptrs[i], sizes[i], ptrs[j], sizes[j])) return -7;
        }
    }
    return 0;
}
static int launch(int group, int variant, const void* a, const void* b, void* out,
                  const void* sfa, const void* sfb, int m, int n, int k, void* stream) {
    const int checked = validate(group, variant, a, b, out, sfa, sfb, m, n, k);
    if (checked) return checked;
    const Args args{static_cast<const unsigned char*>(a), static_cast<const unsigned char*>(b),
        static_cast<unsigned short*>(out), static_cast<const unsigned char*>(sfa),
        static_cast<const unsigned char*>(sfb), n, k, k, k, n, 1, k / 128};
    m1_gemv_dot2_kernel<<<dim3(n / N_LANES), dim3(BLOCK_SIZE), 0,
        reinterpret_cast<hipStream_t>(stream)>>>(args);
    return static_cast<int>(hipGetLastError());
}
#endif // host launch helpers
} // namespace m1_gemv

