        const void* sfa, const void* sfb, void* workspace, uint64_t workspace_bytes,
        int m, int n, int k, void* stream) {
    if (workspace || workspace_bytes) return -8;
    return m1_gemv::launch(group, variant, a, b, out, sfa, sfb, m, n, k, stream);
}

