// SPDX-License-Identifier: Apache-2.0

struct MediumTile { unsigned m,n; };
template<int Mapping,int Group>
__device__ inline MediumTile medium_map_tile(unsigned logical,unsigned gm,unsigned gn) {
if constexpr (Mapping==1) {
const unsigned first_m=(logical/(Group*gn))*Group;
const unsigned actual_m=gm-first_m<Group ? gm-first_m : Group;
const unsigned within=logical%(Group*gn);
return {first_m+within%actual_m,within/actual_m};
} else if constexpr (Mapping==2) {
const unsigned first_n=(logical/(Group*gm))*Group;
const unsigned actual_n=gn-first_n<Group ? gn-first_n : Group;
const unsigned within=logical%(Group*gm);
return {within/actual_n,first_n+within%actual_n};
} else return {logical/gn,logical%gn};
}
#else

// SPDX-License-Identifier: Apache-2.0

struct MediumTile { unsigned m,n; };
template<int Mapping,int Group>
__device__ inline MediumTile medium_map_tile(unsigned logical,unsigned gm,unsigned gn) {
if constexpr (Mapping==1) {
const unsigned first_m=(logical/(Group*gn))*Group;
const unsigned actual_m=gm-first_m<Group ? gm-first_m : Group;
const unsigned within=logical%(Group*gn);
return {first_m+within%actual_m,within/actual_m};
} else if constexpr (Mapping==2) {
const unsigned first_n=(logical/(Group*gm))*Group;
const unsigned actual_n=gn-first_n<Group ? gn-first_n : Group;
const unsigned within=logical%(Group*gm);
